style.css:
@-moz-document domain("roblox.com") {
/* Меняет основной фон сайта */
    body, 
    html,
    .dark-theme, 
    .light-theme, 
    #container-main, 
    .content,
    .main-content,
    .game-details-container,
    .games-carousel-container,
    .section-content {
        background-image: url("https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcS3GQkS3WV-c3Y3XKSco-uKtuFsvjmjTY0e9LL3w-_bNp42p11ag-Zc5FOR&s=10") !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
        background-color: transparent !important; /* Добавлено для прозрачности фона */
    }

    /* Убираем белый фон у основных контейнеров */
    .container-main,
    .main-content,
    .game-details-container,
    .games-carousel-container {
        background-color: transparent !important;
    }

    /* Делает полупрозрачными блоки с играми и текстом */
    .section-content, 
    .game-card-container, 
    .item-card-container,
    .roblox-popover-content,
    .mcl-container,
    .game-card,
    .item-card,
    .card {
        background-color: rgba(255, 255, 255, 0.15) !important;
        backdrop-filter: blur(5px) !important; /* Размытие фона для лучшей читаемости */
        -webkit-backdrop-filter: blur(5px) !important;
        border: 1px solid rgba(255, 255, 255, 0.1) !important;
    }
    
    .dark-theme .section-content, 
    .dark-theme .game-card-container, 
    .dark-theme .item-card-container,
    .dark-theme .game-card,
    .dark-theme .item-card,
    .dark-theme .card {
        background-color: rgba(0, 0, 0, 0.5) !important;
        backdrop-filter: blur(5px) !important;
        -webkit-backdrop-filter: blur(5px) !important;
        border: 1px solid rgba(255, 255, 255, 0.05) !important;
    }

    /* Делаем текст более читаемым на фоне */
    body, 
    .text,
    .game-name,
    .item-name,
    .description {
        color: #ffffff !important;
        text-shadow: 0 2px 4px rgba(0, 0, 0, 0.8) !important;
    }

    /* Для заголовков */
    h1, h2, h3, h4, h5, h6,
    .header-title,
    .section-header {
        color: #ffffff !important;
        text-shadow: 0 2px 8px rgba(0, 0, 0, 0.9) !important;
    }
}
